{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Paclitaxel, a large polycyclic natural product and P-gp substrate, is pumped out of the brain with very low brain concentrations after IV dosing in zebrafish, demonstrating that P-gp-mediated efflux can dominate CNS access for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "In humans, paclitaxel CSF exposure never exceeded ~8% of plasma concentrations, showing extremely limited CNS access for a P-gp substrate with high lipophilicity and large molecular size.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Mithramycin, a glycosylated polyketide natural product, achieved only a 0.12 CSF:plasma ratio in monkeys and little brain distribution, supporting poor CNS penetration for large glycosylated polycyclic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Digitoxin, a cardiac glycoside, had a very low CSF/plasma ratio (0.01-0.03) in dogs, indicating that bulky glycosylated natural products do not easily cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Doxycycline, a polycyclic aromatic antibiotic, showed only traces in rat brain after systemic dosing, supporting poor CNS penetration for this general class of fused-ring antibiotics.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "CMT-3, a lipophilic tetracycline, accumulated in rat brain at 4 µg/g and was considered BBB-permeable, providing a contradictory example that some polycyclic aromatic antibiotics can achieve brain exposure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is doxorubicin, an anthracycline glycoside with a polycyclic quinone and aminosugar. The strongest transferable evidence from large glycosylated/polycyclic natural products (paclitaxel, mithramycin, digitoxin, doxycycline) shows poor CSF/brain exposure and P-gp efflux, while the single permeable tetracycline example is structurally less relevant and insufficient to override the dominant poor-CNS phenotype.",
  "evidence_gaps": [
    "No direct doxorubicin brain/CSF measurement is present in the retrieved evidence set.",
    "Morgan similarities of the retrieved analogues are low (0.20-0.25), so transfer relies on shared physicochemical and transporter liabilities rather than close structural identity.",
    "The query's own P-gp/BCRP efflux status is not directly measured in these records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

